-- generated by `draftpaper apply` (config.toml [session] apps): Neovim as you left it.
-- A file opens with the cursor where it was. Started with no files, Neovim takes up the session it last
-- had in this directory (its tabs, windows and files), saved to stdpath("state")/draftpaper/ as it
-- changes, so a logout that ends it loses nothing.
local group = vim.api.nvim_create_augroup("draftpaper_session", { clear = true })

-- the cursor where it was (the '" mark, kept in shada)
vim.api.nvim_create_autocmd("BufReadPost", {
  group = group,
  callback = function(a)
    local ft = vim.bo[a.buf].filetype
    if vim.bo[a.buf].buftype ~= "" or ft == "gitcommit" or ft == "gitrebase" then return end
    local mark = vim.api.nvim_buf_get_mark(a.buf, '"')
    if mark[1] > 0 and mark[1] <= vim.api.nvim_buf_line_count(a.buf) then
      pcall(vim.api.nvim_win_set_cursor, 0, mark)
    end
  end,
})

-- the session of the directory Neovim started in, when it started with nothing to edit
local dir = vim.fn.stdpath("state") .. "/draftpaper"
local file = dir .. "/" .. vim.fn.getcwd():gsub("%%", "%%%%"):gsub("/", "%%") .. ".vim"
local stdin = false
vim.api.nvim_create_autocmd("StdinReadPre", { group = group, callback = function() stdin = true end })

local function save()
  local files = vim.tbl_filter(function(b)
    return vim.bo[b].buflisted and vim.bo[b].buftype == "" and vim.api.nvim_buf_get_name(b) ~= ""
  end, vim.api.nvim_list_bufs())
  if #files == 0 then
    os.remove(file)
    return
  end
  vim.fn.mkdir(dir, "p")
  local options = vim.o.sessionoptions
  vim.o.sessionoptions = "buffers,curdir,folds,tabpages,winsize"
  pcall(vim.cmd, "silent mksession! " .. vim.fn.fnameescape(file))
  vim.o.sessionoptions = options
end

vim.api.nvim_create_autocmd("VimEnter", {
  group = group,
  nested = true,
  callback = function()
    if vim.fn.argc() > 0 or stdin or vim.api.nvim_buf_get_name(0) ~= "" or vim.bo.modified then return end
    if vim.fn.filereadable(file) == 1 then
      pcall(vim.cmd, "silent source " .. vim.fn.fnameescape(file))
    end
    vim.api.nvim_create_autocmd({ "BufEnter", "BufWritePost", "CursorHold", "FocusLost", "VimLeavePre" }, {
      group = group,
      callback = save,
    })
  end,
})
